let calls = 0, threw = 0, digest = 0;
export function use(value) { calls++; const text = String(value); for (let i = 0; i < text.length; i++) digest = (digest * 31 + text.charCodeAt(i)) | 0; }
export function attempt(f) { try { use(f()); } catch (e) { threw++; use(e && e.name); } }
export function done(name) { console.log(name + ": " + calls + " calls, " + threw + " threw, digest " + (digest >>> 0).toString(16)); }
